const auto invalid = [](const Record& r) { return r.name.empty() || r.age < 0 || r.age > 150; };
for (std::size_t i = 0; i < records.size();) {
    if (invalid(records[i])) records.erase(records.begin() + static_cast<std::ptrdiff_t>(i));
    else ++i;
}

